const config = $('Build Batch Config').item.json;
const vm = $('VM Status Before').item.json;
const stdout = vm.stdout || '';
const diskLine = stdout.split('\n').find((line) => line.includes('/dev/root')) || '';
const diskMatch = diskLine.match(/\s(\d+)G\s+\d+G\s+(\d+)G\s+(\d+)%/);
const freeGb = diskMatch ? Number(diskMatch[2]) : null;
if (!vm.ok || freeGb === null || freeGb < config.minimumFreeGb) {
  throw new Error(`Storage gate failed before GDC batch. freeGb=${freeGb}, minimum=${config.minimumFreeGb}`);
}
return [{ json: { ...config, freeGbBefore: freeGb, storageGate: 'passed' } }];

const config = $('Build Batch Config').item.json;
const before = $('VM Status Before').item.json;
const after = $('VM Status After').item.json;
const status = $('Read Batch Status').item.json;
function parseFreeGb(stdout) {
  const line = String(stdout || '').split('\n').find((value) => value.includes('/dev/root')) || '';
  const match = line.match(/\s(\d+)G\s+\d+G\s+(\d+)G\s+(\d+)%/);
  return match ? Number(match[2]) : null;
}
const freeGbBefore = parseFreeGb(before.stdout);
const freeGbAfter = parseFreeGb(after.stdout);
const stdout = String(status.stdout || '');
const downloadedMatch = stdout.match(/svs=(\d+)/i) || stdout.match(/downloaded[^0-9]*(\d+)/i);
const partialMatch = stdout.match(/partial=(\d+)/i) || stdout.match(/part[^0-9]*(\d+)/i);
const downloaded = downloadedMatch ? Number(downloadedMatch[1]) : null;
const partial = partialMatch ? Number(partialMatch[1]) : null;
const cleanupRecommended = freeGbAfter !== null && freeGbAfter < config.minimumFreeGb;
return [{ json: { ok: status.ok !== false && after.ok !== false, runId: config.runId, limit: config.batchLimit, freeGbBefore, freeGbAfter, downloaded, partial, cleanupRecommended, cleanupEndpoint: `${config.apiBase}/data-batches/gdc/cleanup`, note: cleanupRecommended ? 'Run cleanup only after features/outputs are persisted.' : 'Keep raw slides until preprocess/extract completes.' } }];
